sources.Bootstrap.ets:
export class Bootstrap {
  onCreate(): void {
    const entries = JSON.parse(preferences.get('bookmarks', '[]'))
    store.replace(entries)
  }
}

sources.Persistence.ets:
export class Persistence {
  saveBookmarks(entries: Entry[]): void {
    preferences.set('bookmarks', JSON.stringify(entries))
    preferences.flush()
  }
}

sources.Registry.ets:
export class Registry {
  registerBookmarks(): void {
    registry.register('bookmarks', bookmarkFactory)
  }
}
